/* ================================================================
   Home page (?home): what Kansas Media Stats is and how to keep stats
   on a game, laid out like ESPN's front page: quick links on the left,
   the guide in the middle, what every tracked game gets on the right.
   ================================================================ */
// The front door: the site's plain address opens here. The Game Tracker has its own, ?tracker (and ?edit=<id>).
const PAGE_Q = new URLSearchParams(location.search);
const TRACKER_PAGE = PAGE_Q.has('tracker') || PAGE_Q.has('edit');
const HOME_PAGE = PAGE_Q.has('home') || (!TRACKER_PAGE && !['scores', 'state', 'stats', 'statestats', 'avctl', 'avstats', 'standings', 'game', 'live', 'gamecast', 'team', 'teams'].some(k => PAGE_Q.has(k)));

// On a scorer's device (signed in on the Game Tracker), the menu bar's scorer buttons show on every page too. Away
// from the tracker they open it, with that window up: ?tracker&open=games, setup, export or share.
function scorerBar(){
  let signedIn = false, live = false;
  try {
    // A scorer's device: signed in on the Game Tracker (it notes that at sign-in and clears it at sign-out). Signed
    // out, the bar is just the site's pages, even with games kept here; the Game Tracker link still gets to them.
    signedIn = localStorage.getItem('pressbox.scorer') === '1';
    const d = JSON.parse(localStorage.getItem(STORE) || 'null'), cur = d && d.games && d.games[d.cur];
    live = !!(cur && cur.share && !cur.sample);
  } catch (e) {}
  const go = k => `?tracker&amp;open=${k}`;
  // Signed out: just a Sign in link, to the tracker's Games window with its Sign in with Google button.
  if (!signedIn){
    document.body.classList.add('signin');
    $('#sync').innerHTML = `<a class="abtn" href="${go('games')}" title="Sign in to keep stats and put your games on the scoreboard">Sign in</a>`;
    return;
  }
  document.body.classList.add('scorer');
  $('#sync').innerHTML = `<a class="abtn syncbtn ok" href="${go('games')}" title="Your games are kept in your account"><i></i>Synced</a>`;
  document.querySelector('.navtools .abtns').innerHTML = `<a class="abtn${live ? ' live' : ''}" href="${go('share')}">${live ? '<i></i>Live' : 'Private'}</a>`
    + `<a class="abtn" href="${go('games')}">Games</a>`
    + (localStorage.getItem('pressbox.admin') === '1' ? `<a class="abtn" href="${go('others')}">Others</a>` : '')   // the admin's devices only
    + `<a class="abtn" href="${go('setup')}">Setup</a><a class="abtn" href="${go('export')}">Export</a>`;
}
if (!TRACKER_PAGE) scorerBar();

async function startHome(){
  ui.viewer = true; ui.home = true; document.body.classList.add('viewer', 'bpage');
  $('#board').hidden = false;
  document.title = 'Kansas Media Stats · Track high school football live';
  renderHome();
  try {
    const base = `https://www.gstatic.com/firebasejs/${FIREBASE_VERSION}/firebase-`;
    const [appM, fsM] = await Promise.all([import(base + 'app.js'), import(base + 'firestore.js')]);
    const fsdb = fsM.getFirestore(appM.initializeApp(firebaseConfig));
    scoresReady({fsM, fsdb});   // the week's scores strip
  } catch (e) {}
}

const HOME_CODES = [
  ['A ball at A35 1-10', 'Augusta ball, 1st & 10 at its own 35. Start each drive this way; the down and distance are optional.'],
  ['3-10', '#3 runs for 10 yards'],
  ['3--2', '#3 runs for a loss of 2'],
  ['3-td', '#3 runs it in for a touchdown from wherever the ball is'],
  ['7-88-15', '#7 completes a pass to #88 for 15'],
  ['7-inc', 'Incomplete (7-inc-88 if it was meant for #88)'],
  ['7-sack-6-90', '#7 sacked for a loss of 6 by #90'],
  ['7-int-24-E10', 'Intercepted by #24 at the El Dorado 10'],
  ['15-xp · 15-fg', 'Extra point / field goal good (add -no if it missed)'],
  ['19-punt-40-11-6', '#19 punts 40 yards, #11 returns it 6'],
  ['19-punt ball at E35', 'A punt with no return: the distance works itself out from where El Dorado starts'],
  ['8-5 lateral 11-35', '#8 runs 5, laterals to #11 who goes 35 more'],
  ['19-punt-40-muff-44', 'The punt is muffed by #44 and your team falls on it'],
  ['ko-A25', 'Kickoff; Augusta’s drive starts at its 25'],
  ['pen E 15 pf', '15-yard personal foul on El Dorado'],
  ['pen E 15 pf 1st', 'The same, with an automatic first down (1st, auto or af)'],
  ['28 is now 35', 'A player changed jerseys: everything he does stays on one line in the book'],
  ['to A · eoq · undo', 'Augusta timeout / end of the quarter / take back the last play'],
  ['3-10 8:40 @54', 'Extras on any line: the clock time, and the tackler after @']];

function renderHome(){
  if (!ui.home) return;
  const tracker = '?tracker';
  const icon = d => `<svg viewBox="0 0 20 20" aria-hidden="true"><path d="${d}" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
  const I = {board:'M3 4h14v12H3zM3 8h14M8 8v8', stats:'M4 16V9M10 16V4M16 16v-5', team:'M10 3l6 3v4c0 4-3 6-6 7-3-1-6-3-6-7V6z',
    state:'M3 6l5-2 4 2 5-2v10l-5 2-4-2-5 2zM8 4v10M12 6v10', track:'M3 10h3l2-5 4 10 2-5h3', ext:'M8 4H4v12h12v-4M11 3h6v6M17 3l-8 8',
    list:'M4 5h12M4 10h12M4 15h8', link:'M8 12l4-4M7 9l-2 2a3 3 0 004 4l2-2M13 11l2-2a3 3 0 00-4-4L9 7', shield:'M10 3l6 3v4c0 4-3 6-6 7-3-1-6-3-6-7V6z'};
  // With two leagues' pages here, each stats link says whose it is.
  const links = [['BUCO Scoreboard', '?scores', I.board], ['BUCO Player Stats', '?stats', I.stats], ['BUCO Team Stats', '?stats=team', I.team],
    ['AVCTL Scoreboard', '?avctl', I.board], ['AVCTL Standings', '?standings', I.list], ['AVCTL Player Stats', '?avstats', I.stats], ['AVCTL Team Stats', '?avstats=team', I.team],
    ['State Scoreboard', '?state', I.state], ['Game Tracker', tracker, I.track],
    ['Media Rankings', 'https://kansasmediarankings.com/', I.ext], ['Pick ’Em', 'https://picks.kansasmediarankings.com', I.ext], ['Helmets', 'https://kansasmediarankings.com/helmets.html', I.ext]];
  $('#board').innerHTML = `<div class="hpage">
    <aside class="h-left"><section class="hcard"><h2 class="h-rail">${icon(I.link)}Quick Links</h2>
      <nav class="h-links" aria-label="Quick links">${links.map(([t, h, d]) => `<a href="${esc(h)}">${icon(d)}${esc(t)}</a>`).join('')}</nav></section></aside>

    <section class="hcard h-hero">
      <div class="h-hero-art"><img src="data:image/png;base64," alt="Kansas Media Stats" width="720" height="261"></div>
      <div class="h-hero-bd"><span class="h-eyebrow">Kansas Media Stats</span>
        <h1>Track any high school football game, live</h1>
        <p class="h-dek">Log each play from the press box or the stands. The Gamecast, box score and stats build themselves as you go, and fans follow along with one link.</p>
        <div class="h-btns"><a class="h-btn primary" href="${esc(tracker)}">Start tracking</a><a class="h-btn" href="#how">How it works</a><a class="h-btn" href="?state">Scoreboard</a></div></div>
    </section>

    <div class="h-main">
      <section class="hcard" id="how"><span class="h-eyebrow">How it works</span>
        <h2 class="h-sec">How to track a game</h2>
        <p class="h-p">Anyone can keep stats. All it takes is a phone or a laptop, a roster if you can get one, and a view of the field. You log what happened on each play; the site does the math.</p>
        <p class="h-p"><b>You keep stats on both teams, not just yours.</b> One person tracks the whole game — every snap by either side — and that one game gives both schools their box score, their team stats and their season numbers. Two people tracking the same game from opposite sides would make two half-games, not one good one.</p>
        <ol class="h-steps">
          <li><b>Sign in.</b> Open the <a href="${esc(tracker)}">Game Tracker</a> and tap <b>Sign in to sync</b>, so your games follow you to every device and can go live.</li>
          <li><b>Start the game.</b> Open <b>Games</b> and choose <b>New game</b>, or tap a scheduled game in the scores strip and choose <b>Keep stats on this game</b>. Enter both schools, 11-man or 8-man, and the rosters if you have them (a number and a name on each line).</li>
          <li><b>Type the school’s full name, not initials.</b> “Free State”, not “FS”. The name box suggests schools as you type — take the suggestion, and the school’s helmet or logo and any roster already saved for it fill in on their own. Initials leave the game with a plain monogram and no roster. Use the same spelling when you paste a box score, so its stat lines land on the right team.</li>
          <li><b>It goes live on its own.</b> Once you're signed in, a new game is on the scoreboard, with a link fans can follow. To keep one to yourself, check <b>Keep this game private</b> when you set it up, or tap <b>Live</b> → <b>Make private</b> later.</li>
          <li><b>Log every play by both teams</b>, typing shorthand or tapping buttons — whoever has the ball. The tracker follows possession for you, so you just record what happened. The Gamecast, box score, drives and stats build themselves as you go, for both schools.</li>
          <li><b>Finish.</b> End each quarter as it happens (<code>eoq</code> in shorthand, or the button under the play). When the fourth quarter ends, the game goes Final on every scoreboard.</li>
        </ol>
        <div class="h-modes">
          <div class="h-mode"><span class="h-tag">Fastest</span><h3>Shorthand</h3>
            <p>Type each play as one short line and press Enter. It’s built for a laptop in the press box: once you know it, you can keep up with a hurry-up offense. The line under the box shows how each play will read before you record it.</p>
            <table class="h-codes"><tbody>${HOME_CODES.map(([c, m]) => `<tr><td><code>${esc(c)}</code></td><td>${esc(m)}</td></tr>`).join('')}</tbody></table>
            <p class="h-note">Teams go by a letter of their short name (here A for Augusta and E for El Dorado); the tracker shows which letters right under the box. <b>td</b> always means somebody scored. The full list is under <b>Shorthand</b> in the tracker.</p></div>
          <div class="h-mode"><span class="h-tag blue">Easiest to learn</span><h3>Buttons</h3>
            <p>Tap through each play instead of typing. It’s the best fit on a phone, and a good way to learn the game flow before switching to shorthand.</p>
            <ol>
              <li>Under <b>Next play</b>, tap the kind of play: <b>Run</b>, <b>Pass</b>, <b>Punt</b>, <b>Field Goal</b>, <b>Penalty</b>, <b>Timeout</b> or <b>Note</b> (<b>Kickoff</b> when a team kicks off).</li>
              <li>Fill in the numbers: the ball carrier, or the passer and the receiver; the yards gained or lost; and the tackler if you saw it. The roster chips (#28, #22…) fill in a number with one tap.</li>
              <li>Check the preview, which says exactly how the play will read, then tap <b>Record play</b>.</li>
              <li>Made a mistake? <b>Undo last</b> takes back the latest play, and <b>Edit</b> on any play in the Play-by-Play fixes an older one. Everything after it updates.</li>
            </ol>
            <p class="h-note">In the tracker, <b>Use the full form instead</b> switches to buttons and <b>Back to quick entry</b> switches back. It remembers your choice, and you can switch in the middle of a drive.</p></div>
          <div class="h-mode"><span class="h-tag">Type it how you'd say it</span><h3>Plain English</h3>
            <p>The same box takes a sentence. Write the play the way you’d say it out loud and the tracker works it out — numbers for the players, words for the rest. It’s longer than shorthand but nothing to memorize, and you can mix the two on one line.</p>
            <table class="h-codes h-say"><tbody>${[
              ['3 runs for 9 yards tackled by 55', '#3 rush for 9 yards (#55)'],
              ['3 sacked for 10 yards by 54 3:55', '#3 sacked by #54 for a loss of 10, at 3:55'],
              ['7 pass complete to 88 for 15 yards', 'Completion to #88, first down if it gets there'],
              ['7 incomplete to 88', 'Incomplete, intended for #88'],
              ['7 intercepted by 24', 'Picked off by #24'],
              ['3 runs it in for a touchdown', 'Touchdown from wherever the ball is'],
              ['8 for 9 yards tackled by 55', 'Shortest of all: a number, the yards, the tackler'],
              ['19 punts, 11 returns 5, ball at E35', '#19 punts, #11 returns it 5 — you never work out how far the punt went'],
              ['1 caught the kickoff at the 8 and ran it to the 20', 'Same for kickoffs: the yard lines are the receiving team’s, and the kick’s distance fills itself in'],
              ['3 tackled in the end zone for a safety', 'A safety said plainly (7 sacked in the end zone works too)'],
              ['pen aug 15 personal foul', 'A penalty in words; add 1st for an automatic first down'],
              ['pen aug 5 false start declined', 'Declined: it goes on the log and nothing moves. Offsetting replays the down']
            ].map(([c, m]) => `<tr><td><code>${esc(c)}</code></td><td>${esc(m)}</td></tr>`).join('')}</tbody></table>
            <p class="h-note">Put the clock anywhere on the line (<code>3:55</code>) and the tackler after the play. A few things stay short because there’s no sentence for them: the extra point is <code>15 xp</code> or <code>15 kick good</code>, and a drive starts with <code>A ball at A35</code>.</p></div>
          <div class="h-mode"><span class="h-tag gray">After the game</span><h3>Paste a box score</h3>
            <p>No one at the game to keep stats? Copy the box score from the newspaper or the school and paste it in: tap the game in the scores strip and choose <b>Paste box score</b>, or tap <b>+ Score</b>, then <b>Paste a box score instead</b>.</p>
            <p>The line score, scoring summary and player stats fill in, the game opens to its Box Score, and its stats count toward the season totals.</p></div>
        </div>
      </section>
    </div>

    <aside class="h-right">
      <section class="hcard"><h2 class="h-rail">${icon(I.shield)}Every game you track gets</h2>
        <ul class="h-gets">${[['Gamecast', 'The live field, drive by drive, with each play drawn on it'], ['Box Score', 'Passing, rushing, receiving, kicking and scoring for both teams'],
          ['Play-by-Play', 'Every snap, grouped into drives'], ['Team Stats', 'The two teams side by side: yards, first downs, turnovers and more'],
          ['Its own link', 'Fans follow it live on any phone, with no app or sign-in']].map(([t, d]) => `<li><b>${t}</b><span>${d}</span></li>`).join('')}</ul></section>
    </aside>
  </div>`;
}

